css:
@page { size: A4 landscape; margin: 0; }
html, body { margin: 0; padding: 0; background: #ffffff; direction: ltr; }
.print-format { orientation: landscape; page-size: A4; margin-top: 0mm; margin-bottom: 0mm; margin-left: 0mm; margin-right: 0mm; }
.print-format-gutter, .print-format { direction: ltr !important; margin: 0 !important; padding: 0 !important; width: auto !important; max-width: none !important; min-height: 0 !important; border: 0 !important; box-shadow: none !important; background: #ffffff !important; }
.action-banner { display: none !important; }
.cf-cert { position: relative; width: 1122px; height: 793px; overflow: hidden; background: #ffffff; color: #171717; line-height: 1.3; font-size: 16px; text-align: left; text-rendering: auto; -webkit-print-color-adjust: exact; print-color-adjust: exact; page-break-inside: avoid; }
.cf-cert[dir="rtl"] { text-align: right; }
.cf-cert, .cf-cert * { box-sizing: border-box; }
.cf-cert .cf-t { display: table; border-collapse: collapse; width: 100%; }
.cf-cert .cf-tr { display: table-row; }
.cf-cert .cf-td { display: table-cell; vertical-align: top; }
.cf-cert-sans { font-family: "LMS Sans", "LMS Sans Arabic", sans-serif; }
.cf-cert-serif { font-family: "LMS Serif", "LMS Naskh Arabic", serif; }
.cf-cert .cf-mono { font-family: "LMS Mono", monospace; }
.cf-cert .cf-ltr { direction: ltr; unicode-bidi: embed; }
.cf-cert .cf-muted { color: #525252; }
.cf-cert .cf-soft { color: #383838; }
.cf-cert .cf-bold { font-weight: 700; }
.cf-cert .cf-wrap, .cf-cert .cf-verify { word-wrap: break-word; }
.cf-cert .cf-start { text-align: left; }
.cf-cert .cf-end { text-align: right; }
.cf-cert .cf-center { text-align: center; }
.cf-cert[dir="rtl"] .cf-start { text-align: right; }
.cf-cert[dir="rtl"] .cf-end { text-align: left; }
.cf-cert .cf-middle { vertical-align: middle; }
.cf-cert .cf-bottom { vertical-align: bottom; }
html body .print-format .cf-cert img { width: auto !important; max-width: none !important; max-height: none !important; border: 0; }
.cf-cert .cf-logo { display: block; height: 44px; width: auto; }
.cf-cert .cf-qr { display: block; }
.cf-cert .cf-label { font-size: 13px; color: #525252; }
.cf-cert .cf-value { margin-top: 3px; }
.cf-cert .cf-tight { letter-spacing: -0.02em; }
.cf-cert[dir="rtl"] .cf-tight { letter-spacing: normal; }
.cf-cert-classic .cf-frame { position: absolute; top: 28px; left: 28px; right: 28px; bottom: 28px; border: 2px solid #171717; }
.cf-cert-classic .cf-inner { position: absolute; top: 8px; left: 8px; right: 8px; bottom: 8px; border: 1px solid #525252; padding: 40px 64px 34px; }
.cf-cert-classic .cf-layout { height: 100%; }
.cf-cert-classic .cf-top-row, .cf-cert-classic .cf-foot-row { height: 1px; }
html body .print-format .cf-cert-classic img.cf-qr { width: 78px !important; height: 78px !important; }
.cf-cert-classic .cf-qr-cell { width: 78px; }
.cf-cert-classic[dir="rtl"] .cf-heading { font-style: normal; }
.cf-cert-classic .cf-classic-logo { margin: 0 auto 10px; }
.cf-cert-classic .cf-site { font-size: 16px; letter-spacing: 0.06em; }
.cf-cert-classic .cf-heading { font-size: 42px; font-style: italic; line-height: 1.2; }
.cf-cert-classic .cf-lead { font-size: 18px; margin-top: 26px; }
.cf-cert-classic .cf-verb { margin-top: 16px; }
.cf-cert-classic .cf-name { line-height: 1.15; margin: 12px auto 0; max-width: 880px; }
.cf-cert-classic .cf-rule { width: 380px; height: 1px; background: #7c7c7c; margin: 16px auto 0; }
.cf-cert-classic .cf-title { line-height: 1.25; margin: 10px auto 0; max-width: 820px; }
.cf-cert-classic .cf-foot { table-layout: fixed; }
.cf-cert-classic .cf-foot-side { width: 32%; }
.cf-cert-classic .cf-date { font-size: 17px; }
.cf-cert-classic .cf-expiry { margin-top: 10px; }
.cf-cert-classic .cf-people { font-size: 17px; line-height: 1.35; padding: 0 8px 8px; }
.cf-cert-classic .cf-people-rule { width: 100%; max-width: 340px; height: 1px; background: #525252; margin: 0 auto 6px; }
.cf-cert-classic .cf-id-block { width: auto; }
.cf-cert-classic[dir="ltr"] .cf-id-block { margin-left: auto; }
.cf-cert-classic[dir="rtl"] .cf-id-block { margin-right: auto; }
.cf-cert-classic .cf-id-text { padding: 0 14px; word-wrap: break-word; font-size: 12px; color: #525252; }
.cf-cert-classic .cf-small { font-size: 12px; }
.cf-cert-classic .cf-id { font-size: 13px; color: #171717; margin-top: 3px; }
.cf-cert-classic .cf-verify-label { margin-top: 6px; }
.cf-cert-classic .cf-verify { font-size: 12px; color: #171717; margin-top: 3px; }
.cf-cert-classic[dir="rtl"] .cf-site { letter-spacing: normal; }
